/** How far ahead the overdue job looks when collecting due issues. */
export const OVERDUE_LOOKAHEAD_HOURS: number = 24;

/**
 * Deepest level an issue may occupy. A root issue is level 0; a child sits
 * one level below its parent. Nothing may land deeper than this, including
 * the deepest descendant of an issue that moves with its parent.
 */
export const MAX_SUB_ISSUE_DEPTH: number = 3;

/**
 * Parent/child placement for issues: cycles, the depth cap, and the
 * descendant roll-up. Persistence stays in the issue repository.
 */
import { MAX_SUB_ISSUE_DEPTH } from "@/config/constants";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import type { IssueRollup, IssueStatus } from "@/types/issue";

/** One issue as the hierarchy walk sees it. Archived rows still occupy a level. */
export interface HierarchyLink {
  readonly id: string;
  readonly parentId: string | null;
  readonly status: IssueStatus;
  readonly archivedAt: string | null;
}

export class IssueHierarchyError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: string,
    readonly reason: "cycle" | "too_deep",
  ) {
    super(
      reason === "cycle"
        ? `Issue ${issueId} cannot be placed under itself or under an issue below it.`
        : `Issue ${issueId} would sit deeper than ${MAX_SUB_ISSUE_DEPTH}.`,
    );
    this.name = "IssueHierarchyError";
  }
}

function indexLinks(links: readonly HierarchyLink[]): {
  parentOf: Map<string, string | null>;
  childrenOf: Map<string, string[]>;
} {
  const parentOf = new Map<string, string | null>();
  const childrenOf = new Map<string, string[]>();
  for (const link of links) {
    parentOf.set(link.id, link.parentId);
    if (link.parentId === null) continue;
    const children = childrenOf.get(link.parentId) ?? [];
    children.push(link.id);
    childrenOf.set(link.parentId, children);
  }
  return { parentOf, childrenOf };
}

/** Level of `id` (a root is 0). A loop in the stored parents is a cycle. */
function levelOf(
  id: string,
  parentOf: ReadonlyMap<string, string | null>,
  issueId: string,
): number {
  let level = 0;
  let current: string | null = id;
  const seen = new Set<string>();
  while (current !== null) {
    if (seen.has(current)) throw new IssueHierarchyError(issueId, "cycle");
    seen.add(current);
    if (!parentOf.has(current)) return level;
    const parent = parentOf.get(current) ?? null;
    if (parent === null) return level;
    level += 1;
    current = parent;
  }
  return level;
}

/** True when `nodeId` sits strictly below `ancestorId`. */
function isStrictDescendant(
  nodeId: string,
  ancestorId: string,
  parentOf: ReadonlyMap<string, string | null>,
): boolean {
  let current = parentOf.has(nodeId) ? (parentOf.get(nodeId) ?? null) : null;
  const seen = new Set<string>();
  while (current !== null) {
    if (current === ancestorId) return true;
    if (seen.has(current)) return false;
    seen.add(current);
    if (!parentOf.has(current)) return false;
    current = parentOf.get(current) ?? null;
  }
  return false;
}

/** Longest path of issues strictly below `rootId`, in edges. A leaf spans 0. */
function descendantSpan(
  rootId: string,
  childrenOf: ReadonlyMap<string, readonly string[]>,
): number {
  let max = 0;
  const stack: { id: string; depth: number }[] = (
    childrenOf.get(rootId) ?? []
  ).map((id) => ({ id, depth: 1 }));
  const seen = new Set<string>([rootId]);
  while (stack.length > 0) {
    const item = stack.pop();
    if (item === undefined || seen.has(item.id)) continue;
    seen.add(item.id);
    if (item.depth > max) max = item.depth;
    for (const child of childrenOf.get(item.id) ?? []) {
      stack.push({ id: child, depth: item.depth + 1 });
    }
  }
  return max;
}

/**
 * Rejects a placement that would loop or push the moved issue's deepest
 * descendant past `MAX_SUB_ISSUE_DEPTH`. `parentId === null` makes it a root.
 * `links` must include every issue that could sit above or below this one.
 */
export function assertHierarchyPlacement(
  issueId: string,
  parentId: string | null,
  links: readonly HierarchyLink[],
): void {
  const { parentOf, childrenOf } = indexLinks(links);
  const span = descendantSpan(issueId, childrenOf);
  if (parentId === null) {
    if (span > MAX_SUB_ISSUE_DEPTH) {
      throw new IssueHierarchyError(issueId, "too_deep");
    }
    return;
  }
  if (parentId === issueId || isStrictDescendant(parentId, issueId, parentOf)) {
    throw new IssueHierarchyError(issueId, "cycle");
  }
  const parentLevel = levelOf(parentId, parentOf, issueId);
  if (parentLevel + 1 + span > MAX_SUB_ISSUE_DEPTH) {
    throw new IssueHierarchyError(issueId, "too_deep");
  }
}

/** Live issues in the subtree, root first, skipping rows already archived. */
export function liveIssueIdsInSubtree(
  rootId: string,
  links: readonly HierarchyLink[],
): readonly string[] {
  const { childrenOf } = indexLinks(links);
  const archived = new Map(links.map((link) => [link.id, link.archivedAt !== null]));
  const out: string[] = [];
  const stack = [rootId];
  const seen = new Set<string>();
  while (stack.length > 0) {
    const id = stack.pop();
    if (id === undefined || seen.has(id)) continue;
    seen.add(id);
    if (archived.get(id) !== true) out.push(id);
    const children = childrenOf.get(id) ?? [];
    for (let index = children.length - 1; index >= 0; index -= 1) {
      const child = children[index];
      if (child !== undefined) stack.push(child);
    }
  }
  return out;
}

/** Counts every non-archived issue strictly below `rootId`. */
export function rollupBelow(
  rootId: string,
  links: readonly HierarchyLink[],
): IssueRollup {
  const { childrenOf } = indexLinks(links);
  const byId = new Map(links.map((link) => [link.id, link]));
  let total = 0;
  let open = 0;
  let closed = 0;
  const stack = [...(childrenOf.get(rootId) ?? [])];
  const seen = new Set<string>();
  while (stack.length > 0) {
    const id = stack.pop();
    if (id === undefined || seen.has(id)) continue;
    seen.add(id);
    const link = byId.get(id);
    if (link !== undefined && link.archivedAt === null) {
      total += 1;
      if (
        CLOSED_ISSUE_STATUSES.includes(link.status)
      ) {
        closed += 1;
      } else {
        open += 1;
      }
    }
    for (const child of childrenOf.get(id) ?? []) stack.push(child);
  }
  return { total, open, closed };
}

/** Non-archived issues below an issue, at every depth. */
export interface IssueRollup {
  readonly total: number;
  readonly open: number;
  readonly closed: number;
}

/** One column of the kanban board; the board is an ordered list of these. */
export interface IssueBoardColumn {

