/** Every issue in the org, archived included, for hierarchy walks. */
export async function listHierarchyLinks(
  orgId: OrgId,
): Promise<readonly HierarchyLink[]> {
  const rows = getDb()
    .select({
      id: issues.id,
      parentId: issues.parentId,
      status: issues.status,
      archivedAt: issues.archivedAt,
    })
    .from(issues)
    .where(orgPredicate(issues.orgId, orgId))
    .all();

  return rows.map((row) => ({
    id: row.id,
    parentId: row.parentId,
    status: row.status,
    archivedAt: row.archivedAt,
  }));
}

/** Direct live children, oldest first (creation time, then issue number). */
export async function listChildIssues(
  orgId: OrgId,
  parentId: IssueId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.parentId, parentId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(asc(issues.createdAt), asc(issues.number))
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );
  return rows.map((row) =>
    toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
  );
}

export async function updateIssueParent(
  orgId: OrgId,
  issueId: IssueId,
  parentId: IssueId | null,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({ parentId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);
  const labels = await listLabelsForIssues(orgId, [issueId]);
  return toIssue(row, (labels[issueId] ?? []).map((label) => label.id));
}

