import {
  actorEnvelope,
  issueResource,
  NotFoundError,
  orgResource,
  projectResource,
  requireFound,
} from "./_support";
import type {
  AssignIssueInput,
  ChangeIssueStatusInput,
  CreateIssueInput,
  IssueFilterInput,
  MoveIssueInput,
  SetIssueParentInput,
  UpdateIssueInput,
} from "@/schemas/issue";
import type { IssueId, OrgId, Page, ProjectId } from "@/types/common";
import type {
  Issue,
  IssueBoardColumn,
  IssueRollup,
  IssueWithRelations,
} from "@/types/issue";
import type { Actor } from "@/types/member";

/**
 * The parent must be a live issue of the same project. A different project or
 * workspace is not found; an archived parent is already archived. Depth and
 * cycles are judged against every issue in the org, including ones that move
 * with this issue.
 */
async function assertParentAllowed(
  orgId: OrgId,
  projectId: ProjectId,
  issueId: IssueId,
  parentId: IssueId | null,
): Promise<void> {
  if (parentId !== null) {
    const parent = await issueRepo.findIssueById(orgId, parentId);
    if (parent === null || parent.projectId !== projectId) {
      throw new NotFoundError("Issue", parentId);
    }
    if (parent.archivedAt !== null) {
      throw new AlreadyArchivedError("Issue", parentId);
    }
  }
  const links = await issueRepo.listHierarchyLinks(orgId);
  assertHierarchyPlacement(issueId, parentId, links);
}

const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);
const id = newId();
if (input.parentId !== null) {
  await assertParentAllowed(
    input.orgId,
    input.projectId,
    id,
    input.parentId,
  );
}
const issue = await issueRepo.insertIssue(input, actor.userId, number, id);

input.old_string:
  const archived = await issueRepo.archiveIssue(orgId, issueId);

  await emit("issue.archived", {
    ...actorEnvelope(actor),
    issueId: archived.id,
    projectId: archived.projectId,
  });

  return archived;
}

input.new_string:
  const links = await issueRepo.listHierarchyLinks(orgId);
  const ids = liveIssueIdsInSubtree(issueId, links);
  const archivedRows: Issue[] = [];
  for (const id of ids) {
    archivedRows.push(await issueRepo.archiveIssue(orgId, id as IssueId));
  }

  for (const archived of archivedRows) {
    await emit("issue.archived", {
      ...actorEnvelope(actor),
      issueId: archived.id,
      projectId: archived.projectId,
    });
  }

  const root = archivedRows.find((row) => row.id === issueId);
  return root ?? archivedRows[0] ?? issue;
}

/**
 * Places `issueId` under `parentId`, or makes it a root when `parentId` is
 * null. The issues below it keep their parent and move with it. A refused
 * placement writes nothing and announces nothing.
 */
export async function setIssueParent(
  actor: Actor,
  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  if (before.parentId === input.parentId) return before;

  await assertParentAllowed(
    input.orgId,
    before.projectId,
    before.id,
    input.parentId,
  );

  const after = await issueRepo.updateIssueParent(
    input.orgId,
    input.issueId,
    input.parentId,
  );

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: ["parentId"],
  });

  return after;
}

/** Direct live sub-issues, oldest first. */
export async function listSubIssues(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));
  return issueRepo.listChildIssues(orgId, issueId);
}

/** Open, closed and total counts for every live issue below `issueId`. */
export async function getIssueRollup(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueRollup> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));
  const links = await issueRepo.listHierarchyLinks(orgId);
  return rollupBelow(issueId, links);
}

