/**
 * When a sub-issue stops being open and its direct parent has no open issue
 * left below it, tell that parent's assignee once. Preferences and the
 * "not your own action" rule are `notify`'s. An archived parent, a parent
 * with no assignee, and a parent that still has open work get nothing.
 */
async function maybeNotifySubIssuesCompleted(
  orgId: OrgId,
  issueId: Issue["id"],
  actorId: UserId | null,
): Promise<void> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (issue === null || issue.parentId === null) return;

  const parent = await issueRepo.findIssueById(orgId, issue.parentId);
  if (parent === null || parent.archivedAt !== null || parent.assigneeId === null) {
    return;
  }

  const links = await issueRepo.listHierarchyLinks(orgId);
  if (rollupBelow(parent.id, links).open > 0) return;

  await notify(orgId, "sub_issues_completed", [parent.assigneeId], {
    title: "Sub-issues completed",
    body: `Every open sub-issue under ${parent.id} is finished`,
    href: `/issues/${parent.id}`,
    actorId,
  });
}

